// Open a FILE* from a fuzz-provided filename and wrap it into an ar_stream
// Requirements enforced:
// - Only pass a valid, open FILE* (we bail if fopen fails)
// - Do not use FILE* after giving to ar_open (we don't touch it afterwards)
// - ar_stream must be closed via ar_close by downstream stubs
const char *path = FUZZ_PARAM_FILENAME();
FILE *f = fopen(path, "rb");
if (!f) { FUZZ_BAIL(); }
ar_stream *stream = ar_open(f);
if (!stream) { FUZZ_BAIL(); }
// Track that this stream originated from a FILE* so ar_close doesn't try to free extra resources
FUZZ_SET_ATTR_STR(stream, "origin", "file_handle");
FUZZ_SET_ATTR_INT(stream, "archive_count", FUZZ_GET_ATTR_INT(stream, "archive_count"));
FUZZ_SET_ATTR_INT(stream, "in_entry", 0);
// stream is returned as output and owned by the fuzzer pool now

// Open a stream directly from a path
// Requirements enforced:
// - Provide a valid non-NULL path (FUZZ_PARAM_FILENAME guarantees a real path)
// - On failure, bail to avoid introducing a bad stream into the pool
const char *path = FUZZ_PARAM_FILENAME();
ar_stream *stream = ar_open_file(path);
if (!stream) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_STR(stream, "origin", "path");
FUZZ_SET_ATTR_INT(stream, "archive_count", 0);
FUZZ_SET_ATTR_INT(stream, "in_entry", 0);
// stream is returned as output

// Open a stream over an in-memory buffer. The buffer must remain valid until ar_close.
// We allocate a persistent heap buffer and attach it to the stream so ar_close can free it.
std::string src = FUZZ_PARAM_STR();
size_t len = src.size();
if (len == 0) { FUZZ_BAIL(); }
unsigned char *heap_buf = new unsigned char[len];
memcpy(heap_buf, src.data(), len);
ar_stream *stream = ar_open_memory((const void *)heap_buf, len);
if (!stream) { delete[] heap_buf; FUZZ_BAIL(); }
// Attach lifetime info so ar_close can release it later
FUZZ_SET_ATTR_STR(stream, "origin", "memory");
FUZZ_SET_ATTR_PTR(stream, "mem_buf", (void*)heap_buf);
FUZZ_SET_ATTR_INT(stream, "mem_size", (int)len);
FUZZ_SET_ATTR_INT(stream, "archive_count", 0);
FUZZ_SET_ATTR_INT(stream, "in_entry", 0);
// stream is returned as output

// Close the stream and free any attached user-managed resources.
// Requirements enforced:
// - stream must be a valid ar_stream (the fuzzer runtime supplies one)
// - Do not close while an attached archive is active
int ac = FUZZ_GET_ATTR_INT(stream, "archive_count");
if (ac > 0) { FUZZ_BAIL(); }
// If this stream originated from ar_open_memory, free the backing buffer we allocated
void *buf = FUZZ_GET_ATTR_PTR(stream, "mem_buf");
if (buf) {
    delete[] (unsigned char*)buf;
    FUZZ_SET_ATTR_PTR(stream, "mem_buf", nullptr);
}
// Perform the actual close
ar_close(stream);
// No outputs; the object is dropped from the pool

// Read up to count bytes from the stream. Ensure we do not violate archive in-entry seek rules.
// If this stream is tied to an archive and currently within an entry, we allow read but do not seek.
// ar_read itself is permitted; the restriction is on seeking between parse and uncompress.
size_t count = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
std::string buf; buf.resize(count);
size_t n = ar_read(stream, (void*)buf.data(), count);
// No strong assertions; short reads are allowed. Return stream as output.

// Seek within the stream. Disallow seeking while an archive tied to this stream is mid-entry.
int in_entry = FUZZ_GET_ATTR_INT(stream, "in_entry");
if (in_entry) { FUZZ_BAIL(); }
int which = (int)(*FUZZ_PARAM(unsigned int) % 3);
int origin = which == 0 ? SEEK_SET : (which == 1 ? SEEK_CUR : SEEK_END);
long long off_rng = (long long)(*FUZZ_PARAM(unsigned int) % 2049); // 0..2048
long long sign = (*FUZZ_PARAM(unsigned int) & 1) ? 1 : -1;
off64_t offset = (off64_t)(sign * off_rng);
( void ) ar_seek(stream, offset, origin);
// We don't assert success; return stream regardless.

// Skip relative within the stream. Disallow while mid-entry for any attached archive.
int in_entry = FUZZ_GET_ATTR_INT(stream, "in_entry");
if (in_entry) { FUZZ_BAIL(); }
long long off_rng = (long long)(*FUZZ_PARAM(unsigned int) % 2049);
long long sign = (*FUZZ_PARAM(unsigned int) & 1) ? 1 : -1;
off64_t delta = (off64_t)(sign * off_rng);
( void ) ar_skip(stream, delta);
// Return stream as output.

// Report the current offset. 0 may indicate start or error; we don't disambiguate here.
( void ) ar_tell(stream);
// Return stream as output.

// Close the archive. It does not close the underlying stream.
// Enforce that we are not mid-entry and detach from its stream bookkeeping.
int in_entry = FUZZ_GET_ATTR_INT(ar, "in_entry");
if (in_entry) { FUZZ_BAIL(); }
// Get and update the attached stream's archive_count
ar_stream *s = (ar_stream*)FUZZ_GET_ATTR_PTR(ar, "stream");
if (s) {
    int ac = FUZZ_GET_ATTR_INT(s, "archive_count");
    if (ac > 0) { FUZZ_SET_ATTR_INT(s, "archive_count", ac - 1); }
}
// Perform close
ar_close_archive(ar);
// Drop ar from the pool by not returning it as an output

// Query EOF status following a parse attempt.
( void ) ar_at_eof(ar);
// Return ar as output

// Get the current entry name. Valid only when an entry is active.
if (!FUZZ_GET_ATTR_INT(ar, "in_entry")) { FUZZ_BAIL(); }
( void ) ar_entry_get_name(ar);
// Do not retain the pointer beyond the next parse; return ar.

// Get the offset of the current entry.
if (!FUZZ_GET_ATTR_INT(ar, "in_entry")) { FUZZ_BAIL(); }
off64_t off = ar_entry_get_offset(ar); (void)off;
FUZZ_SET_ATTR_INT(ar, "have_last_offset", 1);
FUZZ_SET_ATTR_INT(ar, "last_offset_lo", (int)(off & 0xFFFFFFFF));
// Return ar

// Get the modification time of the current entry.
if (!FUZZ_GET_ATTR_INT(ar, "in_entry")) { FUZZ_BAIL(); }
( void ) ar_entry_get_filetime(ar);
// Return ar

// Uncompress the next chunk of the current entry into a buffer.
if (!FUZZ_GET_ATTR_INT(ar, "in_entry")) { FUZZ_BAIL(); }
int remaining = FUZZ_GET_ATTR_INT(ar, "remaining");
if (remaining < 0) { remaining = 0; }
size_t max_chunk = (size_t)(remaining > 1024 ? 1024 : remaining);
size_t count = (size_t)(*FUZZ_PARAM(unsigned int) % (max_chunk + 1));
std::string buf; buf.resize(count);
bool ok = ar_entry_uncompress(ar, (void*)buf.data(), count);
if (!ok) { FUZZ_BAIL(); }
// Update remaining and clear in_entry when done
int new_remaining = remaining - (int)count;
FUZZ_SET_ATTR_INT(ar, "remaining", new_remaining);
if (new_remaining == 0) { FUZZ_SET_ATTR_INT(ar, "in_entry", 0); }
// Return ar

// Fetch the global comment, either by querying size or copying to a buffer.
int do_query_only = (int)(*FUZZ_PARAM(unsigned int) & 1);
if (do_query_only) {
    ( void ) ar_get_global_comment(ar, nullptr, 0);
} else {
    size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024);
    std::string buf; buf.resize(cap);
    ( void ) ar_get_global_comment(ar, (void*)buf.data(), cap);
}
// Return ar as output

// Open a RAR archive on the provided stream. The stream remains caller-owned and must be closed separately.
// Enforce: stream must be positioned at start and not mid-entry. We cannot guarantee format correctness; bail if mid-entry.
if (FUZZ_GET_ATTR_INT(stream, "in_entry")) { FUZZ_BAIL(); }
ar_archive *ar = ar_open_rar_archive(stream);
if (!ar) { FUZZ_BAIL(); }
// Link archive to stream and track state
FUZZ_SET_ATTR_PTR(ar, "stream", (void*)stream);
FUZZ_SET_ATTR_INT(ar, "in_entry", 0);
FUZZ_SET_ATTR_INT(ar, "remaining", 0);
FUZZ_SET_ATTR_INT(ar, "have_last_offset", 0);
// Increment stream's attached archive count so ar_close can refuse premature close
int ac = FUZZ_GET_ATTR_INT(stream, "archive_count");
FUZZ_SET_ATTR_INT(stream, "archive_count", ac + 1);
// Also mirror in_entry flag on stream for seek/skip guards
FUZZ_SET_ATTR_INT(stream, "in_entry", 0);
// Return both stream (still owned by caller) and new archive as outputs

// Parse the next archive entry. On success, record that an entry is active and cache size/offset.
// Enforce: do not call while already in an active entry (per API warning about seeking/uncompress cycle).
if (FUZZ_GET_ATTR_INT(ar, "in_entry")) { FUZZ_BAIL(); }
bool ok = ar_parse_entry(ar);
if (ok) {
    FUZZ_SET_ATTR_INT(ar, "in_entry", 1);
    // Cache entry size and clamp to a safe int range for our bookkeeping of remaining bytes.
    size_t sz = ar_entry_get_size(ar);
    int remaining_cap = (int)(sz > (size_t)1048576 ? 1048576 : sz); // clamp to 1 MiB for safety
    FUZZ_SET_ATTR_INT(ar, "remaining", remaining_cap);
    // Capture an offset hint for potential ar_parse_entry_at usage.
    off64_t off = ar_entry_get_offset(ar); (void)off;
    FUZZ_SET_ATTR_INT(ar, "have_last_offset", 1);
    FUZZ_SET_ATTR_INT(ar, "last_offset_lo", (int)(off & 0xFFFFFFFF));
}
// Return ar either way; caller may query ar_at_eof(ar) on false
// Validation: Ensures not mid-entry on call; on success sets in_entry and a bounded remaining budget.

// Parse the entry at a specific offset (0 restarts from the first entry).
// Enforce: not currently within an entry, and use only allowed offsets (0 is always valid per API).
if (FUZZ_GET_ATTR_INT(ar, "in_entry")) { FUZZ_BAIL(); }
// Favor 0 as a universally valid offset to honor the API contract safely.
off64_t offset = 0;
bool ok = ar_parse_entry_at(ar, offset);
if (ok) {
    FUZZ_SET_ATTR_INT(ar, "in_entry", 1);
    size_t sz = ar_entry_get_size(ar);
    int remaining_cap = (int)(sz > (size_t)1048576 ? 1048576 : sz);
    FUZZ_SET_ATTR_INT(ar, "remaining", remaining_cap);
}
// Validation: Only uses offset 0 (guaranteed valid); sets in_entry/remaining on success.

// Locate and parse the first entry with the given name.
// Enforce: not currently within an entry. Provide a valid C string from fuzz input.
if (FUZZ_GET_ATTR_INT(ar, "in_entry")) { FUZZ_BAIL(); }
std::string name = FUZZ_PARAM_STR();
const char *entry_name = name.c_str();
bool ok = ar_parse_entry_for(ar, entry_name);
if (ok) {
    FUZZ_SET_ATTR_INT(ar, "in_entry", 1);
    size_t sz = ar_entry_get_size(ar);
    int remaining_cap = (int)(sz > (size_t)1048576 ? 1048576 : sz);
    FUZZ_SET_ATTR_INT(ar, "remaining", remaining_cap);
}
// Validation: Guards mid-entry calls; initializes remaining budget on success.

// Get the uncompressed size of the current entry and refresh remaining budget for uncompress.
if (!FUZZ_GET_ATTR_INT(ar, "in_entry")) { FUZZ_BAIL(); }
size_t sz = ar_entry_get_size(ar);
int remaining_cap = (int)(sz > (size_t)1048576 ? 1048576 : sz);
FUZZ_SET_ATTR_INT(ar, "remaining", remaining_cap);
// Validation: Requires an active entry; updates bounded remaining count.

// Open a TAR archive on the provided stream. Stream remains caller-owned.
// Enforce: stream must not be mid-entry and is assumed positioned at start of TAR data.
if (FUZZ_GET_ATTR_INT(stream, "in_entry")) { FUZZ_BAIL(); }
ar_archive *ar = ar_open_tar_archive(stream);
if (!ar) { FUZZ_BAIL(); }
// Link archive to stream and initialize bookkeeping.
FUZZ_SET_ATTR_PTR(ar, "stream", (void*)stream);
FUZZ_SET_ATTR_INT(ar, "in_entry", 0);
FUZZ_SET_ATTR_INT(ar, "remaining", 0);
FUZZ_SET_ATTR_INT(ar, "have_last_offset", 0);
// Increment stream's attached archive count for lifetime management.
int ac = FUZZ_GET_ATTR_INT(stream, "archive_count");
FUZZ_SET_ATTR_INT(stream, "archive_count", ac + 1);
// Validation: Ensures stream state is compatible; returns both stream and opened archive.

// Open a ZIP archive on the provided stream. Stream remains caller-owned.
// Enforce: stream not mid-entry; choose deflatedonly based on fuzz input.
if (FUZZ_GET_ATTR_INT(stream, "in_entry")) { FUZZ_BAIL(); }
bool deflatedonly = ((*FUZZ_PARAM(unsigned int)) & 1) != 0;
ar_archive *ar = ar_open_zip_archive(stream, deflatedonly);
if (!ar) { FUZZ_BAIL(); }
// Link archive to stream and initialize bookkeeping.
FUZZ_SET_ATTR_PTR(ar, "stream", (void*)stream);
FUZZ_SET_ATTR_INT(ar, "in_entry", 0);
FUZZ_SET_ATTR_INT(ar, "remaining", 0);
FUZZ_SET_ATTR_INT(ar, "have_last_offset", 0);
// Increment stream's attached archive count.
int ac = FUZZ_GET_ATTR_INT(stream, "archive_count");
FUZZ_SET_ATTR_INT(stream, "archive_count", ac + 1);
// Validation: Respects ownership and deflatedonly parameter; sets consistent state.

// Open a 7Z archive on the provided stream. Stream remains caller-owned.
// Enforce: stream not mid-entry; assume positioned at start of 7Z data.
if (FUZZ_GET_ATTR_INT(stream, "in_entry")) { FUZZ_BAIL(); }
ar_archive *ar = ar_open_7z_archive(stream);
if (!ar) { FUZZ_BAIL(); }
// Link archive to stream and initialize bookkeeping.
FUZZ_SET_ATTR_PTR(ar, "stream", (void*)stream);
FUZZ_SET_ATTR_INT(ar, "in_entry", 0);
FUZZ_SET_ATTR_INT(ar, "remaining", 0);
FUZZ_SET_ATTR_INT(ar, "have_last_offset", 0);
// Increment stream's attached archive count.
int ac = FUZZ_GET_ATTR_INT(stream, "archive_count");
FUZZ_SET_ATTR_INT(stream, "archive_count", ac + 1);
// Validation: Ensures correct stream state and archive lifetime accounting.
